bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
docker exec -i "$cid" node --input-type=module <<'JS'
import {readFileSync,readdirSync} from 'node:fs';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
const root='/opt/videobot/src';
const all=[], calls=[];
function walk(p) {
 for (const e of readdirSync(p,{withFileTypes:true})) {
  const file=join(p,e.name);
  if(e.isDirectory())walk(file);
  else if(e.isFile()&&file.endsWith('.mjs')){
   const data=readFileSync(file);
   const source=data.toString();
   const sha=createHash('sha1').update(Buffer.from('blob '+data.length+'\0')).update(data).digest('hex');
   all.push({p:file.slice(root.length+1),sha});
   const lines=source.split('\n');
   for(let i=0;i<lines.length;i++)if(/sendPaidMedia|sendVideo|sendMediaGroup|copyMessage|forwardMessage|paid_video_file_id|paidVideo\.fileId|paidMedia\.paid_media|nativePaid/.test(lines[i]))calls.push({p:file.slice(root.length+1),line:i+1,code:lines[i].trim().slice(0,125)});
  }
 }
}
walk(root);
console.log('TOTAL_SOURCE_MODULES='+all.length);
console.log('RELEVANT_CALLS='+calls.length);
for(const v of calls)console.log(JSON.stringify(v));
const must=['telegram/paidListingPublisher.mjs','telegram/paidMedia.mjs','telegram/freeAlbum.mjs','telegram/creatorWizard.mjs','telegram/creatorWiring.mjs','telegram/creatorBot.mjs','sales/pgPostingReceipts.mjs','sales/pgStarsLedger.mjs'];
for(const path of must){const f=all.find(x=>x.p===path);console.log('CRITICAL_MODULE '+path+' '+(f?.sha||'MISSING'));}
JS
docker inspect "$cid" --format 'CONTAINER_RUNNING={{.State.Running}} IMAGE={{.Config.Image}}'
